from datetime import datetime, timedelta
from functools import partial
from funcy import cache, reraise, SkipMemoization

calls = []
@cache(60, key_func=lambda x: x % 2)
def cached(x):
    calls.append(x)
    return x
assert cached.memory == {}
assert cached.skip is SkipMemoization
assert cached(1) == cached(3) == 1
assert cached.memory[1][0] == 1
cached.memory.clear()
assert cached(3) == 3
cached.memory[1] = (9, datetime.now())
assert cached(1) == 9
cached.memory[1] = (9, datetime.now() - timedelta(seconds=61))
assert cached(1) == 1
cached.invalidate(1)
assert cached.memory == {}
cached(0)
cached.invalidate_all()
assert cached.memory == {}

@cache(60)
def skipped(value=None):
    raise skipped.skip(value)
assert skipped(42) == 42
assert skipped() is None
assert skipped.memory == {}

original = ValueError('original')
def check(target, expected_args, expected_instance=None):
    try:
        with reraise(ValueError, target):
            raise original
    except RuntimeError as exc:
        assert exc.args == expected_args
        assert exc.__cause__ is original
        if expected_instance is not None:
            assert exc is expected_instance
    else:
        raise AssertionError('did not raise')
check(RuntimeError, ())
instance = RuntimeError('fixed')
check(instance, ('fixed',), instance)
check(lambda exc: RuntimeError(str(exc)), ('original',))
check(partial(lambda prefix, exc: RuntimeError(prefix + str(exc)), 'new: '), ('new: original',))
class CallableError(RuntimeError):
    def __call__(self, exc):
        raise AssertionError('exception instance must not be called')
instance = CallableError('callable exception')
check(instance, ('callable exception',), instance)

seen = []
@reraise(ValueError, lambda exc: (seen.append(exc), RuntimeError(str(exc)))[1])
def decorated(fail):
    if fail:
        raise original
    return 42
assert decorated(False) == 42
for _ in range(2):
    try:
        decorated(True)
    except RuntimeError as exc:
        assert exc.__cause__ is original
assert seen == [original, original]
try:
    with reraise(ValueError, lambda exc: seen.append(exc)):
        raise KeyError('unmatched')
except KeyError:
    pass
assert seen == [original, original]
print('Targeted cache and reraise checks passed')
